<script setup>
import { computed, ref } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import PageHeader from '../../../Components/Ui/PageHeader.vue';
import StatRail from '../../../Components/Ui/StatRail.vue';
import EmptyState from '../../../Components/Ui/EmptyState.vue';

defineOptions({layout:AdminLayout});
const props=defineProps({employee:{type:Object,required:true},summary:{type:Object,required:true},monthLabel:String,items:{type:Array,default:()=>[]},itemsTotal:String,charges:{type:Array,default:()=>[]},can:{type:Object,required:true},urls:{type:Object,required:true}});
const waiveTarget=ref(null);
const settle=useForm({amount:Number(props.summary.outstanding||0).toFixed(2),method:'payroll_deduction',notes:''});
const waive=useForm({amount:'',method:'gift',reason:''});
const openCharges=computed(()=>props.charges.filter(charge=>!charge.settled));
const usageTone=computed(()=>Number(props.summary.usage_pct)>=100?'danger':Number(props.summary.usage_pct)>=80?'warning':'success');
function settleNow(){settle.post(props.urls.settle,{preserveScroll:true})}
function openWaive(charge){waiveTarget.value=charge;waive.amount=Number(charge.amount).toFixed(2);waive.method='gift';waive.reason='';waive.clearErrors()}
function waiveNow(){waive.post(waiveTarget.value.waiveUrl,{preserveScroll:true,onSuccess:()=>waiveTarget.value=null})}
</script>
<template>
<Head :title="`بدل وجبات ${employee.name}`"/>
<PageHeader :title="employee.name" icon="bi-cup-hot-fill" :subtitle="`حساب بدل الوجبات · ${monthLabel}`" :crumbs="[{label:'بدل وجبات الموظفين',url:urls.index}]"><template #actions><a :href="urls.quickConsume" class="btn btn-light"><i class="bi bi-plus-lg"></i> إضافة استهلاك</a></template></PageHeader>
<StatRail :stats="[{label:'الحد الشهري',value:summary.allowanceFormatted,icon:'bi-speedometer2',color:'muted'},{label:'قيمة الوجبات',value:summary.usedFormatted,icon:'bi-cup-straw',color:'accent'},{label:'تحمله المطعم',value:summary.coveredFormatted,icon:'bi-shield-check',color:'success'},{label:'المتبقي من الحد',value:summary.remainingFormatted,icon:'bi-pie-chart-fill',color:Number(summary.remaining)<0?'danger':'success'},{label:'مستحق كل الأشهر',value:summary.outstandingFormatted,icon:'bi-wallet2',color:'warning'}]"/>
<section v-if="summary.usage_pct!==null" class="usage-card" :class="`is-${usageTone}`"><div><span>استخدام بدل الشهر</span><strong>{{summary.usage_pct}}%</strong></div><div><i :style="{width:`${Math.min(100,Number(summary.usage_pct))}%`}"></i></div><small v-if="Number(summary.overflow)>0">تجاوز الحد بقيمة {{summary.overflow}}</small><small v-else>المتبقي {{summary.remainingFormatted}}</small><b v-if="Number(summary.gifted)>0"><i class="bi bi-gift-fill"></i> هدايا هذا الشهر {{summary.giftedFormatted}}</b></section>
<section v-if="summary.outstanding>0&&can.settle" class="settlement"><header><div><small>تحصيل أو خصم</small><h2>تسوية المستحق</h2></div><strong>{{summary.outstandingFormatted}}</strong></header><form @submit.prevent="settleNow"><label><span>المبلغ *</span><input v-model="settle.amount" type="number" min="0.01" :max="summary.outstanding" step="0.01" required></label><label><span>الطريقة *</span><select v-model="settle.method"><option value="payroll_deduction">خصم من الراتب</option><option value="cash">دفع نقدي</option><option value="writeoff">شطب إداري</option></select></label><label class="notes"><span>ملاحظة</span><input v-model="settle.notes" maxlength="500" placeholder="مثال: راتب شهر آب"></label><button class="btn btn-primary" :disabled="settle.processing"><i class="bi bi-check2-circle"></i> تأكيد التسوية</button></form><p><i class="bi bi-info-circle"></i> يبدأ النظام بأقدم الحركات المفتوحة أولاً (FIFO) ويبقي السجل كاملاً.</p></section>
<div class="detail-grid"><section class="items-panel"><header><div><small>تفصيل {{monthLabel}}</small><h2>ما استهلكه الموظف</h2></div><strong>{{itemsTotal}}</strong></header><div v-if="items.length" class="items"><article v-for="item in items" :key="item.name"><span>{{item.name[0]}}</span><div><strong>{{item.name}}</strong><small>متوسط {{item.averagePrice}}</small></div><b>×{{item.quantity}}</b><em>{{item.total}}</em></article></div><EmptyState v-else icon="bi-cup-hot" title="لا استهلاك هذا الشهر" message="ستظهر الأصناف هنا بعد أول عملية."/></section><section class="charges-panel"><header><div><small>آخر {{charges.length}} حركة</small><h2>سجل الوجبات والمستحقات</h2></div><span>{{openCharges.length}} مستحقة</span></header><div v-if="charges.length" class="charges"><article v-for="charge in charges" :key="charge.id" :class="{settled:charge.settled}"><div class="charge-main"><strong>{{charge.orderNumber||'تعديل يدوي'}}</strong><small>{{charge.date}}</small></div><div class="charge-money"><b>{{charge.consumptionFormatted}}</b><small v-if="charge.amount>0">على الموظف {{charge.amountFormatted}}</small><small v-else>تحمله المطعم {{charge.coveredFormatted}}</small><span :class="charge.settled?'done':'open'">{{charge.settled?(charge.methodLabel||'ضمن البدل'):'مستحق'}}</span></div><p v-if="charge.notes">{{charge.notes}}</p><button v-if="!charge.settled&&can.waive" type="button" @click="openWaive(charge)"><i class="bi bi-gift"></i> إعفاء</button></article></div><EmptyState v-else icon="bi-clock-history" title="لا حركات بعد" message="لا يوجد شيء مسجّل على هذا الموظف."/></section></div>
<Teleport to="body"><Transition name="fade"><div v-if="waiveTarget" class="backdrop" @click.self="waiveTarget=null"><form class="waive-card" @submit.prevent="waiveNow"><header><div><small>{{waiveTarget.orderNumber||`حركة #${waiveTarget.id}`}}</small><h2>إعفاء من الحركة</h2></div><button type="button" @click="waiveTarget=null"><i class="bi bi-x-lg"></i></button></header><div class="charge-summary"><span>قيمة الحركة</span><strong>{{waiveTarget.amountFormatted}}</strong></div><label><span>قيمة الإعفاء *</span><input v-model="waive.amount" type="number" min="0.01" :max="waiveTarget.amount" step="0.01" required><small>يمكن إعفاء جزء من الحركة أو كاملها.</small></label><label><span>نوع الإعفاء *</span><select v-model="waive.method"><option value="gift">هدية / مكافأة موظف</option><option value="writeoff">شطب إداري</option></select></label><label><span>السبب</span><input v-model="waive.reason" maxlength="500" placeholder="مثال: عيد ميلاد أو تعويض"></label><footer><button type="button" class="btn btn-light" @click="waiveTarget=null">تراجع</button><button class="btn btn-primary" :disabled="waive.processing"><i class="bi bi-check2"></i> تنفيذ الإعفاء</button></footer></form></div></Transition></Teleport>
</template>
<style scoped>
