font-size:.62rem}.items{padding:.35rem .8rem}.items article{display:grid;grid-template-columns:34px 1fr 44px 90px;gap:.55rem;align-items:center;padding:.55rem 0;border-bottom:1px solid #edf1ef}.items article>span{width:34px;height:34px;border-radius:9px;background:#eaf5ee;color:#107140;display:grid;place-items:center;font-weight:900}.items article>div{display:grid}.items article strong{font-size:.69rem}.items article small{font-size:.59rem;color:#819087}.items article>b{color:#177443;font-size:.68rem}.items article>em{text-align:end;font-size:.67rem;font-style:normal;font-weight:800}.charges{display:grid}.charges article{display:grid;grid-template-columns:1fr auto auto;gap:.55rem;align-items:center;padding:.7rem .9rem;border-bottom:1px solid #edf1ef}.charges article.settled{opacity:.68}.charge-main,.charge-money{display:grid}.charge-main strong{font-size:.69rem}.charge-main small{font-size:.59rem;color:#819087}.charge-money{text-align:end}.charge-money b{font-size:.7rem}.charge-money span{font-size:.58rem}.charge-money .open{color:#a76d0a}.charge-money .done{color:#177443}.charges article>p{grid-column:1/3;margin:0;font-size:.62rem;color:#738279}.charges article>button{grid-column:3;grid-row:1/3;border:1px solid #cbe2d4;background:#f3faf5;color:#167443;border-radius:9px;padding:.38rem .5rem;font-size:.63rem}.backdrop{position:fixed;inset:0;z-index:2100;background:rgba(9,31,19,.5);display:grid;place-items:center;padding:1rem}.waive-card{width:min(440px,100%);background:#fff;border-radius:17px;padding:1rem;display:grid;gap:.7rem}.waive-card header{display:flex;justify-content:space-between}.waive-card h2,.waive-card small{margin:0}.waive-card h2{font-size:1rem}.waive-card header small{font-size:.64rem;color:#819087}.waive-card header button{border:0;background:#f0f4f2;border-radius:9px;width:36px;height:36px}.charge-summary{display:flex;justify-content:space-between;padding:.7rem;background:#f3f8f5;border-radius:10px;font-size:.7rem}.charge-summary strong{color:#117140}.waive-card label{display:grid;gap:.3rem}.waive-card label>span{font-size:.68rem;font-weight:800}.waive-card input,.waive-card select{border:1px solid #dce5df;border-radius:9px;padding:.55rem;background:#fff}.waive-card label small{font-size:.61rem;color:#819087}.waive-card footer{display:flex;justify-content:flex-end;gap:.5rem}.fade-enter-active,.fade-leave-active{transition:.18s}.fade-enter-from,.fade-leave-to{opacity:0}@media(max-width:1000px){.settlement form{grid-template-columns:1fr 1fr}.settlement .notes{grid-column:1/-1}.detail-grid{grid-template-columns:1fr}}@media(max-width:600px){.settlement form{grid-template-columns:1fr}.settlement .notes{grid-column:auto}.items article{grid-template-columns:32px 1fr 36px 70px}.charges article{grid-template-columns:1fr auto}.charges article>button{grid-column:2;grid-row:2}.charges article>p{grid-column:1}}
</style>
